let data;
try {
  data = JSON.parse($json.choices[0].message.content);
} catch (e) {
  data = { reply: 'Désolée, pouvez-vous répéter ?', complet: false, candidat: {} };
}
const c = data.candidat || {};
return [{ json: {
  reply: data.reply || '',
  complet: data.complet === true,
  date: new Date().toISOString().slice(0, 10),
  heure: new Date().toTimeString().slice(0, 5),
  sessionId: $('Préparer la conversation').item.json.sessionId,
  type: c.type || '', nom: c.nom || '', telephone: c.telephone || '', email: c.email || '',
  ville: c.ville || '', details: c.details || '', disponibilites: c.disponibilites || '',
  score: c.score || '', resume: c.resume || ''
} }];

const PROMPT = "Tu es l'assistant d'un fondateur qui développe une application de livraison de repas. Écris en français la synthèse de recrutement du jour, en HTML simple (h2, h3, ul, li, b, p ; pas de balise html/body). Structure : 1) Chiffres clés (total, par type). 2) Top 3 des meilleurs profils avec pourquoi. 3) Liste par catégorie (Livreurs, Restaurants, Développeurs) avec contact. 4) Actions à faire demain (qui rappeler en priorité). 5) Conseil pour améliorer le recrutement. Sois concis.";
const today = new Date().toISOString().slice(0, 10);
const rows = $input.all().map(i => i.json).filter(r => String(r.Date) === today);
const lignes = rows.map((r, i) => `${i + 1}. [${r.Type}] ${r.Nom} - ${r.Ville} - tel ${r['Téléphone']} - ${r.Email} - score ${r.Score}/10 - ${r['Détails']} - dispo: ${r['Disponibilités']} - ${r['Résumé']}`);
const parType = {};
rows.forEach(r => { parType[r.Type || 'Autre'] = (parType[r.Type || 'Autre'] || 0) + 1; });
return [{ json: { today, total: rows.length, parType, prompt: PROMPT, texte: lignes.join('\n') || 'Aucun candidat aujourd\'hui.' } }];
